  {"clause_id": "c002", "issues": [
    {"issue": "\"Design of a full campaign plan\" states no content, deliverable or completion standard, so what would discharge the obligation is undefined. The introductory promise that the scope \"clearly defines\" the services is in tension with so open-ended an item.", "type": 1, "prob": 0.22},
    {"issue": null, "type": 2, "prob": 0.07}
