  {"clause_id": "c006", "issues": [
    {"issue": null, "type": 1, "prob": 0.15},
    {"issue": "This sentence conditions all third-party research billing on client approval, while section 4.2(c) requires prior approval only for Third-party Expenses of $1,000 or more. The two approval regimes cannot both govern research costs below that threshold.", "type": 2, "prob": 0.22}
  ]},
  {"clause_id": "c007", "issues": [
    {"issue": null, "type": 1, "prob": 0.11},
    {"issue": null, "type": 2, "prob": 0.06}
  ]},
  {"clause_id": "c008", "issues": [
    {"issue": "\"Undertake education activities to inform them\" sets no measurable content or volume, and \"them\" depends on the antecedent in the preceding sentence. What counts as performance cannot be fixed from the words.", "type": 1, "prob": 0.16},
    {"issue": null, "type": 2, "prob": 0.06}
  ]},
  {"clause_id": "c009", "issues": [
    {"issue": "A national \"breakout\" story is an undefined and unmeasurable objective, and \"on-going news stories\" sets no frequency. The clause states an aspiration rather than an ascertainable duty.", "type": 1, "prob": 0.18},
    {"issue": null, "type": 2, "prob": 0.07}
  ]},
  {"clause_id": "c010", "issues": [
    {"issue": "\"[B]est efforts\" is undefined and the provision supplies no benchmark against which placement efforts could be measured. The disclaimer that placement \"is not guaranteed\" leaves the residual obligation to be construed.", "type": 1, "prob": 0.32},
    {"issue": null, "type": 2, "prob": 0.08}
  ]},
  {"clause_id": "c011", "issues": [
    {"issue": "\"[K]ey publications\" has no defined boundary, and the promise \"to write and place op-ed columns\" sits against section 1.1's acknowledgment elsewhere that placement is not guaranteed. Neither the number nor the identity of publications is fixed.", "type": 1, "prob": 0.20},
    {"issue": null, "type": 2, "prob": 0.08}
  ]},
  {"clause_id": "c012", "issues": [
    {"issue": "\"[A]s necessary to groups likely to support the Client's efforts such as the U.S. Chamber of Commerce\" attaches a single specific example to an open general class. The extent of the outreach duty cannot be determined from the words.", "type": 1, "prob": 0.18},
    {"issue": null, "type": 2, "prob": 0.06}
  ]},
  {"clause_id": "c013", "issues": [
    {"issue": "\"[B]uild a relevant audience\" specifies no size, platform or metric, so performance is unmeasurable. \"[O]ne or more platforms\" leaves the scope entirely to the promisor.", "type": 1, "prob": 0.17},
    {"issue": null, "type": 2, "prob": 0.06}
  ]},
  {"clause_id": "c014", "issues": [
    {"issue": "\"[P]eriodic monitoring\" fixes no interval and \"rapid response\" no time limit. The frequency of the promised service is therefore indeterminate.", "type": 1, "prob": 0.17},
    {"issue": null, "type": 2, "prob": 0.06}
