  {"clause_id": "c024", "issues": [
    {"issue": "\"[D]uring or for a period of one year following the conclusion of this Agreement\" does not say whether \"conclusion\" means expiry, termination under 2.2, or completion of work. \"[O]ffers of employment\" is also undefined as against hiring an applicant who approaches the party.", "type": 1, "prob": 0.28},
    {"issue": null, "type": 2, "prob": 0.09}
  ]},
  {"clause_id": "c025", "issues": [
    {"issue": "The sentence is grammatically tangled: \"any individuals then-currently employed by the applicable Party during the term of the Agreement either directly or through a third party\" mixes a present-tense reference point with a term-long window, so the covered class is uncertain. It is unclear whether \"through a third party\" describes the employment or the offer.", "type": 1, "prob": 0.35},
    {"issue": null, "type": 2, "prob": 0.08}
