  {"clause_id": "c026", "issues": [
    {"issue": "\"[D]amages equal to one year of the employee's gross salary\" does not say whose salary figure governs — the old employer's or the new one's — or at what date it is measured. Whether this liquidated sum is the exclusive remedy is also unstated.", "type": 1, "prob": 0.33},
    {"issue": null, "type": 2, "prob": 0.08}
